 async function applyPurchaseLink(row,{quiet=false,catalog=null}={}){
  if(row.querySelector('[name="line_type"]').value==='expense')return false;
  const identity=purchaseIdentity(row);if(!identity.supplier_id){if(!quiet)throw new Error('Önce kayıtlı tedarikçiyi seçin. Yeni tedarikçiyle taslağı kaydedip yeniden açabilirsiniz.');return false;}
  const data=catalog||await api('/catalog'),mapping=purchaseCandidate(data,identity),status=row.querySelector('[data-purchase-status]');
  if(!mapping){if(!quiet)status.textContent='Bu tedarikçi adı/kodu ve birimi için kayıtlı bağlantı bulunamadı. Ürünü seçip bağlantıyı hatırlatabilirsiniz.';return false;}
  const components=data.components.filter(c=>c.mapping_id===mapping.id);if(components.length!==1)throw new Error('Alış bağlantısı tek stok kartına bağlanmalı.');
  const component=components[0],total=identity.invoice_quantity*component.quantity_milli;
  if(!Number.isFinite(total)||Math.abs(total-Math.round(total))>0.000001||total<=0||total>1000000000)throw new Error('Birim dönüşümü stok hassasiyetine uygun değil.');
  row.querySelector('[name="product_id"]').value=component.product_id;row.querySelector('[name="stock_quantity"]').value=Math.round(total)/1000;row.dataset.catalogMappingId=mapping.id;
  const product=state.data.stock.find(p=>p.id===component.product_id);status.textContent='Kayıtlı bağlantı uygulandı: '+(product?.name||'Ürün')+' · '+qty(Math.round(total))+' '+(product?.stock_unit||'')+'. Kaydetmeden önce kontrol edin.';return true;
 }
 async function rememberPurchaseLink(row){
  const identity=purchaseIdentity(row),status=row.querySelector('[data-purchase-status]');
  if(row.querySelector('[name="line_type"]').value==='expense')throw new Error('Yalnızca stok ürünü satırı için bağlantı kaydedilir.');
  if(!identity.supplier_id||!identity.product_id||!identity.source_unit||(!identity.external_code&&!identity.external_name)||identity.invoice_quantity<=0||identity.stock_quantity<=0)throw new Error('Önce tedarikçi, ürün, fatura birimi ve miktarları tamamlayın.');
  const conversion=identity.stock_quantity/identity.invoice_quantity*1000;
  if(!Number.isFinite(conversion)||Math.abs(conversion-Math.round(conversion))>0.000001||conversion<=0)throw new Error('Bir fatura biriminin stok karşılığı en fazla üç ondalık olmalı.');
  const data=await api('/catalog'),current=purchaseCandidate(data,identity);
  const result=await post('/catalog/mappings',{source:'purchase',supplier_id:identity.supplier_id,external_code:identity.external_code,external_name:identity.external_name,source_unit:identity.source_unit,match_by:identity.external_code?'code':'name',...(current?{replaces_id:current.id}:{}),components:[{product_id:identity.product_id,quantity_milli:Math.round(conversion),revenue_share_bps:10000}]});
  row.dataset.catalogMappingId=result.id;status.textContent='Bağlantı kaydedildi. Aynı tedarikçi, '+(identity.external_code?'ürün kodu':'tam ürün adı')+' ve fatura birimi sonraki alışlarda bu stok kartına bağlanacak.';
 }

 function invoiceLine(line={},index=0){return `<div class="ac-invoice-line" data-invoice-line="${index}"><div class="ac-line-title"><strong>Satır ${index+1}</strong><button class="text-button danger" data-ac="remove-invoice-line" type="button">Kaldır</button></div>${field('Faturadaki ürün açıklaması','description',line.description||'','text','required maxlength="300"')}<div class="field-grid">${field('Fatura miktarı','invoice_quantity',line.invoice_quantity??1,'number','required min="0.001" max="1000000" step="0.001"')}${field('Fatura birimi','invoice_unit',line.invoice_unit||'adet','text','required maxlength="30"')}${amountField('Satır net tutarı · KDV hariç','net',line.net??'',true)}${amountField('Satır KDV tutarı','tax',line.tax??'',true)}</div>${field('Tedarikçi ürün kodu','external_code',line.external_code||'')}${select('Satır türü','line_type',[['product','Stok ürünü'],['expense','Hizmet / gider']],line.line_type||'product')}${select('Gider türü (hizmet satırıysa)','expense_category',Object.entries(categories).filter(([k])=>!['loss','purchase_variance','purchase_correction'].includes(k)),line.expense_category||'other')}${treatmentField(line.expense_treatment||'')}<p class="help" data-expense-help>Kargo ve komisyonun satışlarda izlenen kısmını genel gider olarak tekrar yazmayın. Kesinti seçimi cari borcu oluşturur; satışlara dağıtım ayrıca tamamlanır.</p><div class="field-grid">${select('Bizdeki ürün · eşleştirme','product_id',[['','Henüz eşleştirme'],...productOptions()],'')}${field('Bizim stok birimimize göre giriş miktarı','stock_quantity',line.invoice_quantity??1,'number','required min="0.001" max="1000000" step="0.001"')}</div></div>`;}
