 function splitHistory(inv){return (inv.splits||[]).map(s=>'<div class="notice subtle"><strong>Faturanın asıl satırı: '+esc(s.original.description)+'</strong><p>'+esc(s.original.invoice_quantity)+' '+esc(s.original.invoice_unit)+' · Net '+money(s.original.net_cents)+' · KDV '+money(s.original.tax_cents)+'</p><p>Dağılım dayanağı: '+esc(s.reason)+' · '+(s.status==='active'?'Çeşitlere dağıtıldı':'Dağılım geri alındı')+'</p>'+(s.status==='active'&&inv.status==='draft'?button('Dağılımı geri al','undo-split','type="button" data-id="'+s.id+'"',true):'')+'</div>').join('');}
