 async function purchaseReturnForm(key){const inv=await api('/invoices/'+key);const lines=inv.lines.filter(l=>l.line_type==='product').map(l=>({...l,remaining:l.received_milli-(inv.returns||[]).filter(r=>r.line_id===l.id&&!r.reversal_of&&!r.reversed_by).reduce((s,r)=>s+r.quantity_milli,0)})).filter(l=>l.remaining>0);if(!lines.length)throw Error('Bu faturada iade edilebilir teslim miktarı yok.');dialog('Tedarikçiye ürün iadesi','purchase-return',field('Fatura','invoice_id',key,'hidden')+'<div class="notice subtle">Fiziksel olarak geri gönderilen ürün stoktan çıkar; alış faturasındaki orantılı net bedel ve KDV kadar tedarikçi borcu azalır. Resmî iade faturası düzenlenmez; ilgili belgenin referansını kaydedin. İade edilmeyen satırı sıfır bırakın.</div>'+dates()+field('İade belgesi / referansı','reference','','text','required maxlength="200"')+field('İade gerekçesi','reason','','text','required maxlength="500"')+lines.map(l=>'<div class="ac-invoice-line" data-purchase-return-line="'+l.id+'">'+field(l.description+' · en fazla '+qty(l.remaining),'quantity',0,'number','required min="0" max="'+l.remaining/1000+'" step="0.001"')+'</div>').join('')+'<p class="help">Fiyat farkı / iskontolu iade ve hizmet faturası düzeltmesi bu ekrandan işlenmez. Stokta siparişlere ayrılmış miktar korunur.</p>');}
