   if(kind==='invoice-filters'){state.invoiceQuery=entries.q;state.invoiceStatus=entries.status;state.invoiceSort=entries.sort||'';state.invoicePage=1;await load();return;}
   if(kind==='purchase-adjustment'){await post('/invoices/'+entries.invoice_id+'/adjustments',{...entries,net:number('net'),tax:number('tax'),stock_net:number('stock_net'),quantity:number('quantity')});}
