 root.addEventListener('input',()=>{const box=$('[data-variant-total]');if(box){const total=$$('[data-variant] input').reduce((sum,i)=>sum+Number(i.value||0),0),expected=Number($('[name="total_quantity"]')?.value||0);box.textContent='Dağıtılan: '+qty(Math.round(total*1000))+' / '+qty(Math.round(expected*1000))+' · Kalan: '+qty(Math.round((expected-total)*1000));}},{signal:controller.signal});
