  if(action==='purchase-document'){close();disposeUpload?.();const view=$('#ac-view')||root;disposeUpload=mountInvoiceUpload(view,namespace,{user:currentUser,signal:controller.signal,onClose:async x=>{state.busy=false;try{await load();if(controller.signal.aborted)return;if(x?.manual)newInvoice();else $('[data-ac="purchase-document"]')?.focus();}catch(error){if(error.name!=='AbortError')notice(error.message);}}});return;}
  if(action==='invoice-reset'){Object.assign(state,{invoiceQuery:'',invoiceStatus:'',invoiceSort:'',invoicePage:1});await load();$('[data-ac-form="invoice-filters"] [name="q"]')?.focus();return;}
