  if(action==='add-variant'){const rows=$('[data-variant-rows]');if(rows.children.length>=20)throw Error('En fazla 20 çeşit dağıtılabilir.');const fam=$('dialog [name="family_id"]')?.value||'';rows.insertAdjacentHTML('beforeend',splitRow(fam?familyProductOptions(fam):null));refreshVariantTotals();return;}
  if(action==='undo-split'){await post('/invoices/'+state.invoice.id+'/splits/'+key+'/undo',{});await reviewInvoice(state.invoice.id);return;}
