  if(action==='purchase-return'){await purchaseReturnForm(key);return;}
  if(action==='reverse-receipt'||action==='reverse-purchase-return'){const inv=state.invoice;dialog(action==='reverse-receipt'?'Yanlış mal teslimini geri al':'Tedarikçi iadesini geri al','purchase-reverse',field('Fatura','invoice_id',inv.id,'hidden')+field('İşlem','target',action==='reverse-receipt'?'receipts/'+key+'/reverse':'returns/'+key+'/reverse','hidden')+dates()+field('Düzeltme referansı','reference',ref('DUZELT'),'text','required')+field('Düzeltme gerekçesi','reason','','text','required maxlength="500"')+'<p class="help">Eski kayıt korunur. Mal teslimini geri almak stoğu azaltır ve tekrar teslim girişi açar; iade kaydını geri almak ürünü stoğa ve borcu cariye geri ekler. Yalnızca fiili durumla uyumlu düzeltme yapın.</p>');return;}
  if(action==='cancel-invoice'){dialog('Taslağı işleme alma','cancel-invoice',field('Fatura','invoice_id',key,'hidden')+'<p>Bu taslak stok veya borç oluşturulmadan vazgeçildi olarak saklanır. Aynı belgeyi yeniden içe aktarmak yerine geçmişi koruyun.</p>');return;}
