  if(action==='add-invoice-line'){const container=$('#ac-invoice-lines');if(container.children.length>=40)throw new Error('En fazla 40 fatura satırı eklenebilir.');container.insertAdjacentHTML('beforeend',invoiceLine({},container.children.length));decoratePurchaseRows();return;}
